CREATE TABLE IF NOT EXISTS deduplicated_reagent_catalog AS 
SELECT DISTINCT * FROM reagent_catalog; 

SELECT * FROM deduplicated_reagent_catalog;

CREATE TABLE IF NOT EXISTS reagent_catalog (id INTEGER PRIMARY KEY, cas_number TEXT, chemical_name TEXT); 
INSERT INTO reagent_catalog (cas_number, chemical_name) VALUES 
('64-17-5', 'Ethanol'), 
('7732-18-5', 'Water'), 
('64-17-5', 'Ethanol'), 
('67-56-1', 'Methanol'); 

CREATE TABLE IF NOT EXISTS deduplicated_reagent_catalog AS 
SELECT DISTINCT * FROM reagent_catalog; 

SELECT * FROM deduplicated_reagent_catalog;

CREATE TABLE IF NOT EXISTS deduplicated_reagent_catalog AS 
SELECT DISTINCT cas_number, chemical_name FROM reagent_catalog; 

-- Now we export the deduplicated data as a CSV payload -- 
WITH csv_data AS (
  SELECT * FROM deduplicated_reagent_catalog
) 
SELECT
  group_concat(cas_number || ',' || chemical_name, '\n') AS csv_payload
FROM csv_data;

